mockup.css:
.mock-hero-stacked-word-tower { background: #101010; color: #f5f2ea;
  font-family: "Helvetica Neue", Inter, ui-sans-serif, sans-serif;
  display: flex; flex-direction: column; justify-content: center; padding: 5cqw; gap: .4cqw; }
.mock-hero-stacked-word-tower .w { font-weight: 800; text-transform: uppercase; line-height: .86;
  letter-spacing: -.04em; display: block; }
.mock-hero-stacked-word-tower .w1 { font-size: 11.5cqw; }
.mock-hero-stacked-word-tower .w2 { font-size: 15.5cqw; }
.mock-hero-stacked-word-tower .w3 { font-size: 8.4cqw; }
.mock-hero-stacked-word-tower .tail { display: flex; justify-content: space-between; margin-top: 3cqw;
  font-size: 1.6cqw; letter-spacing: .16em; text-transform: uppercase; opacity: .6; }
